<script setup>
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { request } from '../../services/api'
const dishes=ref([]), category=ref('全部'), active=ref({}), note=ref(''), tableNo=ref('A08'), remark=ref(''), orders=ref([]), loading=ref(true)
const cats=['全部','主食','小食','饮品'];const filtered=computed(()=>dishes.value.filter(x=>category.value==='全部'||x.category===category.value));const count=computed(()=>Object.values(active.value).reduce((a,b)=>a+b,0));const total=computed(()=>dishes.value.reduce((sum,d)=>sum+(active.value[d.id]||0)*d.price,0))
async function load(){try{dishes.value=await request('/api/dishes');orders.value=await request(`/api/orders?tableNo=${tableNo.value}`)}catch(e){note.value=e.message||'服务暂不可用'}finally{loading.value=false}}
function add(d){active.value={...active.value,[d.id]:(active.value[d.id]||0)+1};uni.showToast({title:'已加入餐篮',icon:'success'})}function minus(d){const n=Math.max(0,(active.value[d.id]||0)-1);active.value={...active.value,[d.id]:n}}
async function submit(){try{const items=Object.entries(active.value).filter(([,q])=>q>0).map(([dishId,quantity])=>({dishId:Number(dishId),quantity}));if(!items.length)throw Error('请先选择菜品');const result=await request('/api/orders','POST',{tableNo:tableNo.value,note:remark.value,items});orders.value=[result,...orders.value];active.value={};note.value=`下单成功，订单 #${result.id} 已提交后厨`;uni.showToast({title:'下单成功',icon:'success'})}catch(e){note.value=e.message||'下单失败'}}
onLoad(load)
</script>
<template>
<view class="page">
  <view class="nav"><view><text class="brand">食刻</text><text class="nav-sub">SMART DINING</text></view><view class="table-badge">桌号 {{tableNo}} <text>⌄</text></view></view>
  <view class="hero-card"><view><text class="eyebrow">GOOD FOOD · GOOD MOOD</text><text class="title">这一餐，慢慢吃</text><text class="subtitle">扫码即点 · 少等一会儿 · 现做更好吃</text><view class="hero-tags"><text>现点现做</text><text>约 15 分钟</text></view></view><view class="hero-icon">🍜</view></view>
  <view class="table-row"><view><text class="table-label">正在为哪张桌服务？</text><text class="table-hint">桌号用于匹配本桌订单</text></view><input v-model="tableNo" maxlength="12" @blur="load"/><text class="table-edit">编辑</text></view>
  <view class="section-head"><view><text class="section-title">今日菜单</text><text class="section-desc">精选好味道，马上开吃</text></view><text class="section-link">{{dishes.length}} 道菜</text></view>
  <scroll-view scroll-x class="cats"><text v-for="c in cats" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</text></scroll-view>
  <view v-if="loading" class="empty">正在加载菜单...</view>
  <view v-else class="menu"><view v-for="d in filtered" :key="d.id" class="dish"><view class="dish-icon">{{d.icon}}<text v-if="d.badge" class="badge">{{d.badge}}</text></view><view class="dish-info"><view><text class="dish-name">{{d.name}}</text><text class="dish-desc">{{d.desc}}</text></view><view class="dish-bottom"><view><text class="price">¥{{d.price}}</text><text class="price-tip">每份</text></view><view class="stepper"><button @click="minus(d)" :disabled="!active[d.id]">−</button><text>{{active[d.id]||0}}</text><button @click="add(d)">＋</button></view></view></view></view></view>
  <view class="section-head note-head"><view><text class="section-title">用餐备注</text><text class="section-desc">口味、餐具或过敏需求</text></view></view><view class="remark-wrap"><text class="remark-icon">✎</text><input v-model="remark" class="remark" placeholder="例如：少辣、不要香菜、需要餐具"/></view>
  <view class="section-head orders-title"><view><text class="section-title">本桌订单</text><text class="section-desc">实时查看后厨制作进度</text></view><text class="section-link">{{orders.length}} 笔</text></view>
  <view v-for="o in orders" :key="o.id" class="order"><view><text class="order-id">订单 #{{o.id}} <text>· ¥{{o.total}}</text></text><text class="order-detail">{{o.items.map(x=>x.name+'×'+x.quantity).join('、')}}</text></view><text class="status">{{o.status}}</text></view><view v-if="!orders.length" class="empty-panel">还没有提交过订单</view>
  <view class="bottom"><view><text class="bottom-count">餐篮 {{count}} 件</text><text class="bottom-total">合计 ¥{{total}}</text></view><button @click="submit" :disabled="!count">提交订单 <text>→</text></button></view><view v-if="note" class="toast">{{note}}</view>
</view>
</template>
